'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var tape = require( 'tape' );
var instanceOf = require( '@stdlib/assert/instance-of' );
var Legend = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Legend, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function is a constructor', function test( t ) {
	var legend = new Legend({
		'fill': 'colorScale'
	});
	t.strictEqual( instanceOf( legend, Legend ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor does not require the `new` keyword', function test( t ) {
	var legend;
	var ctor;

	ctor = Legend;
	legend = ctor({
		'fill': 'colorScale'
	});
	t.strictEqual( instanceOf( legend, Legend ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor does not require the `new` keyword (options)', function test( t ) {
	var legend;
	var ctor;

	ctor = Legend;
	legend = ctor({
		'fill': 'colorScale',
		'direction': 'horizontal'
	});
	t.strictEqual( instanceOf( legend, Legend ), true, 'returns expected value' );
	t.strictEqual( legend.direction, 'horizontal', 'returns expected value' );
	t.end();
});

tape( 'the constructor throws an error if provided an options argument which is not an object', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5,
		NaN,
		null,
		void 0,
		true,
		false,
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var legend = new Legend( value ); // eslint-disable-line no-unused-vars
		};
	}
});

tape( 'the constructor throws an error if not provided at least one legend scale property', function test( t ) {
	t.throws( foo, TypeError, 'throws an error' );
	t.end();

	function foo() {
		var legend = new Legend({ // eslint-disable-line no-unused-vars
			'direction': 'vertical'
		});
	}
});

