tape( 'the constructor ignores unrecognized options', function test( t ) {
	var legend;

	legend = new Legend({
		'fill': 'colorScale',
		'beep': 'boop',
		'foo': 'bar'
	});

	t.strictEqual( legend.fill, 'colorScale', 'returns expected value' );
	t.strictEqual( legend.beep, void 0, 'returns expected value' );
	t.strictEqual( legend.foo, void 0, 'returns expected value' );

	t.end();
});
